mutations.after:
onClick={() => {
  onSelectLayer(row.id);
  dispatch({ type: "setLayerEnabled", id: row.id, enabled: row.off });
}}

const [pickedIndex, setPickedIndex] = useState<number | null>(null);
const pickedLayerId =
  pickedIndex === null ? null : (rawLayerStackProps.rows[pickedIndex]?.id ?? null);
const setPickedLayerId = (next: string | null | ((prev: string | null) => string | null)) => {
  const id = typeof next === "function" ? next(pickedLayerId) : next;
  setPickedIndex(id === null ? null : rawLayerStackProps.rows.findIndex((row) => row.id === id));
};

mutations.before:
useEffect(() => {
  setPickedLayerId((id) =>
    id !== null && !state.template.layers.some((layer) => layer.id === id) ? null : id,
  );
}, [state.template.layers]);
